/**
 * Generates the build-time relay defaults used by the desktop app, Chrome extension and Android
 * app. The relay URL and shared secret are intentionally compiled into the clients so setup stays
 * to one passphrase (and a PIN on mobile).
 *
 * The generated files contain a shared secret. They are gitignored; run `pnpm relay:defaults`
 * after changing .env.local or before a clean build.
 */
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");

function parseEnv(text) {
  const values = {};
  for (const line of text.split(/\r?\n/)) {
    const match = line.match(/^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)\s*$/);
    if (!match) continue;
    let value = match[2].trim();
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }
    values[match[1]] = value;
  }
  return values;
}

const env = parseEnv(readFileSync(resolve(root, ".env.local"), "utf8"));
const relayUrl = (env.RELAY_URL ?? "").trim().replace(/\/+$/, "");
const relaySecret = (env.RELAY_SECRET ?? "").trim();

if (!relayUrl || !/^https?:\/\//i.test(relayUrl)) {
  throw new Error("RELAY_URL is missing or invalid in .env.local");
}
if (!relaySecret) throw new Error("RELAY_SECRET is missing in .env.local");

const header = "// Generated by scripts/generate-relay-defaults.mjs. Do not edit by hand.\n";
const ts = `${header}export const RELAY_URL = ${JSON.stringify(relayUrl)};\nexport const RELAY_SECRET = ${JSON.stringify(relaySecret)};\n`;
const kotlinSecret = JSON.stringify(relaySecret).replaceAll("$", "\\$");
const kotlinUrl = JSON.stringify(relayUrl).replaceAll("$", "\\$");
const kotlin = `package com.recall.app.config

// Generated by scripts/generate-relay-defaults.mjs. Do not edit by hand.
object RelayDefaults {
    const val URL = ${kotlinUrl}
    const val SECRET = ${kotlinSecret}
}
`;

const files = [
  [resolve(root, "apps/desktop/src/lib/relay-defaults.ts"), ts],
  [resolve(root, "apps/chrome-ext/src/lib/relay-defaults.ts"), ts],
  [resolve(root, "apps/android/app/src/main/java/com/recall/app/config/RelayDefaults.kt"), kotlin],
];

for (const [file, body] of files) {
  mkdirSync(dirname(file), { recursive: true });
  writeFileSync(file, body, "utf8");
  console.log(`wrote ${file}`);
}
